import {commonCases,commonCase,createCommonPair,commonPairModel,splitCommonPair,undoCommonPair,compareCommonPair,commonExample} from './common-cuts-core.mjs';
import {commonCopy as copy,commonOriginalText,commonCurrentText,commonUnitText,commonChangeText} from './common-cuts-content.mjs';
import {commonRibbonArt} from './common-cuts-art.mjs';
import {hearButton} from './play-media.mjs';
import {groupPiecesPage,bindGroupPieces,resetGroupPieces} from './group-pieces-ui.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null,retireBinding=()=>{},stopBinding=()=>{};
export function resetCommonCuts(){retireBinding();stopBinding();stopBinding=()=>{};visit=null;resetGroupPieces();}
function current(state,explorerId){if(!visit||visit.notebook!==state||visit.explorerId!==explorerId){resetCommonCuts();visit={notebook:state,explorerId,mode:'cuts',caseId:null,pairs:new Map(),comparison:false,exampleOpen:false,exampleFrame:0,cutHelpOpen:false};}return visit;}
// Retained controls cannot return to life after a mode switch or DOM removal.
function commonGuard(root,valid,stop){
 const controls=[root,...root.querySelectorAll('button,select,a,details,summary')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.target.closest?.('.speech-controls,drawn-howto'))continue;if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{disconnected=true;observer.disconnect();};retireBinding=disconnect;
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});
 observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return node=>{audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||retired.has(node)||node.disabled)return false;const before=chains.get(node),now=chain(node);if(!before||before.length!==now.length||!before.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;};
}
const button=(attributes,label,disabled=false)=>`<button type="button" ${attributes}${disabled?' disabled':''}>${esc(label)}</button>`;
function catalog(selected){return `<div class="common-catalog">${commonCases.map(c=>button(`data-common-start="${c.id}" ${selected&&c.id===selected?'aria-current="true"':''}`,`${c.title}: A ${c.left.numerator}/${c.left.denominator}, B ${c.right.numerator}/${c.right.denominator}`)).join('')}</div>`;}
const compactReadout=m=>`Still ${m.originalNumerator}/${m.originalDenominator}; ${m.coloredCount} of ${m.denominator} equal pieces colored. Each piece is 1/${m.denominator} of the whole.`;
function row(m,side,example=false){const letter=side==='left'?'A':'B';return `<section class="common-row" data-common-model="${side}" data-numerator="${m.numerator}" data-denominator="${m.denominator}" data-original="${m.originalNumerator}/${m.originalDenominator}"><h3 data-common-read>Ribbon ${letter} <span>started as ${m.originalNumerator}/${m.originalDenominator}</span> <strong>Now ${m.numerator}/${m.denominator}</strong></h3>${commonRibbonArt(m,side,example?'example':'live')}<p class="common-readout" data-common-read data-common-readout>${esc(compactReadout(m))}</p>${example?'':`<div class="common-actions" role="group" aria-label="Change Ribbon ${letter}">${button(`data-common-split="${side}" data-factor="2" aria-label="Ribbon ${letter}: ${copy.split2}"`,copy.split2,!m.canSplit2)}${button(`data-common-split="${side}" data-factor="3" aria-label="Ribbon ${letter}: ${copy.split3}"`,copy.split3,!m.canSplit3)}${button(`data-common-undo="${side}" aria-label="Ribbon ${letter}: ${copy.undo}"`,copy.undo,!m.canUndo)}</div>`}</section>`;}
function cutExplanation(m,v){return `<details data-common-cut-help${v.cutHelpOpen?' open':''}><summary>How the cuts work</summary>${['left','right'].map((side,i)=>`<h3>Ribbon ${i?'B':'A'}</h3><p data-common-read>${esc(commonOriginalText(i?'B':'A',m[side]))} ${esc(commonCurrentText(m[side]))} ${esc(commonUnitText(m[side]))} ${esc(commonChangeText(m[side]))}</p>`).join('')}</details>`;}
function narration(v){
 const m=v.exampleOpen?commonExample(v.exampleFrame):commonPairModel(v.pairs.get(v.caseId)),c=commonCase(v.caseId);if(!m)return '';
 return `${v.exampleOpen?`${copy.exampleLabel} ${copy.exampleNotice}`:`${c.title}. ${c.request}`} ${copy.whole} ${['left','right'].map((s,i)=>`Ribbon ${i?'B':'A'}. ${compactReadout(m[s])}`).join(' ')} ${v.exampleOpen?`Picture ${v.exampleFrame+1} of 3. ${m.text}`:v.comparison?compareCommonPair(v.pairs.get(v.caseId)).text:''}`;
}
function visibleNarration(root){return [...root.querySelectorAll('[data-common-read]')].filter(node=>{for(let p=node.parentElement;p&&p!==root;p=p.parentElement)if(p.tagName==='DETAILS'&&!p.open)return false;return true;}).map(node=>node.textContent.replace(/\s+/g,' ').trim()).join(' ');}
function example(v){const m=commonExample(v.exampleFrame);return `<div data-common-view="example"><h2 id="common-board-title" data-common-read tabindex="-1">${copy.exampleLabel}</h2><p data-common-read>${copy.exampleNotice}</p><p class="common-whole-note" data-common-read>${copy.whole}</p>${row(m.left,'left',true)}${row(m.right,'right',true)}<p id="common-example-caption" data-common-read tabindex="-1" role="status">Picture ${v.exampleFrame+1} of 3. ${esc(m.text)}</p><nav class="common-actions" aria-label="Example pictures">${button('data-common-example-previous',copy.previous,v.exampleFrame===0)}${button('data-common-example-next',copy.next,v.exampleFrame===2)}${button('data-common-example-close',copy.back)}</nav>${hearButton(narration(v),copy.hear)}</div>`;}
function board(v){const c=commonCase(v.caseId),pair=v.pairs.get(v.caseId),m=commonPairModel(pair);if(!c||!m)return '';
 return `<div data-common-view="case" data-common-case="${c.id}"><h2 id="common-board-title" data-common-read tabindex="-1">${esc(c.title)}</h2><p class="common-request" data-common-read>${esc(c.request)}</p><p class="common-whole-note" data-common-read>${copy.whole}</p>${row(m.left,'left')}${row(m.right,'right')}<p class="common-cut-key" data-common-read>Dashed marks: new cuts. Solid marks: surviving boundaries. Brass flags: fixed colored ends.</p><div class="common-board-actions">${button('data-common-compare',copy.compare)}${hearButton(narration(v),copy.hear)}${button('data-common-example-open',copy.exampleLabel)}</div>${v.comparison?`<p id="common-comparison" class="common-comparison" role="status" tabindex="-1" data-common-comparison data-common-read>${esc(compareCommonPair(pair).text)}</p>`:''}${cutExplanation(m,v)}<p class="common-bound">${copy.bound}</p><details class="common-chooser"><summary>Choose another pair</summary><p>${copy.chooseAnother}</p>${catalog(c.id)}</details><details><summary>Talk together</summary><p>${copy.talk}</p></details></div>`;
}
export function commonCutsPage(state,explorerId){const v=current(state,explorerId);return `<section class="common-page" data-common-root><header class="common-heading"><nav aria-label="Nearby tables"><a href="#workshop/recut">Ribbon Recut</a><a href="#numbers/lanterns">Lantern Line</a><a href="#cafe/portions">Join the Portions</a><a href="#workshop/join-pieces">Join the Pieces</a></nav><h1>${copy.title}</h1><a class="pill" href="#workshop/ribbon-measures">Measure with a ribbon</a>${v.mode==='cuts'&&!v.caseId?`<p>${copy.introduction}</p>`:''}</header><nav class="common-modes" aria-label="Ribbon table modes">${['cuts','groups'].map(mode=>`<button type="button" data-common-mode="${mode}" aria-pressed="${v.mode===mode}">${mode==='cuts'?'Compare cuts':'Group pieces'}</button>`).join('')}</nav><div class="common-worktop">${v.mode==='groups'?groupPiecesPage(state,explorerId):`${v.exampleOpen?example(v):v.caseId?board(v):`<div data-common-view="chooser"><h2 id="common-board-title" data-common-read tabindex="-1">${copy.chooser}</h2><p>${copy.whole}</p>${catalog(null)}</div>`}<p class="common-visit">${copy.visit}</p><details class="common-grownup"><summary>For grown-ups</summary><p>${copy.grownUp}</p></details>`}</div></section>`;}
export function bindCommonCuts(state,ctx){
 retireBinding();
 const root=document.querySelector('[data-common-root]');if(!root||!visit)return;
 const captured=visit,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,mode=visit.mode,caseId=visit.caseId,pairRef=visit.pairs.get(caseId),pairBytes=JSON.stringify(pairRef),exampleOpen=visit.exampleOpen,frame=visit.exampleFrame;
 const notebook=()=>typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??state;
 const parentLive=()=>root.isConnected&&document.querySelector('[data-common-root]')===root&&location.hash==='#workshop/common-cuts'&&notebook()===state&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===captured&&visit.notebook===state&&visit.explorerId===owner&&visit.mode===mode;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};stopBinding=stop;
 const allowed=commonGuard(root,parentLive,stop);
 root.querySelectorAll('[data-common-mode]').forEach(b=>b.addEventListener('click',()=>{if(!allowed(b)||!['cuts','groups'].includes(b.dataset.commonMode)||b.dataset.commonMode===mode)return;stop();visit.mode=b.dataset.commonMode;ctx.render();ctx.focus(visit.mode==='groups'?'#gp-heading':'#common-board-title');}));
 if(mode==='groups'){bindGroupPieces(state,{...ctx,isActive:parentLive});return;}
 const live=()=>parentLive()&&visit.caseId===caseId&&visit.pairs.get(caseId)===pairRef&&JSON.stringify(pairRef)===pairBytes&&visit.exampleOpen===exampleOpen&&visit.exampleFrame===frame;
 root.querySelector('[data-common-cut-help]')?.addEventListener('toggle',e=>{if(live()&&allowed(e.target))visit.cutHelpOpen=e.target.open;});
 const redraw=(selector='#common-board-title')=>{ctx.render();const target=document.querySelector(selector);ctx.focus(target&&!target.disabled?selector:'#common-board-title');};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(!live()||!allowed(b))return;fn(b);}));
 on('[data-common-start]',b=>{const id=b.dataset.commonStart;if(!commonCase(id))return;stop();if(!visit.pairs.has(id))visit.pairs.set(id,createCommonPair(id));visit.caseId=id;visit.comparison=false;visit.exampleOpen=false;redraw();});
 const change=(b,undo)=>{if(exampleOpen)return;const side=undo?b.dataset.commonUndo:b.dataset.commonSplit,next=undo?undoCommonPair(pairRef,side):splitCommonPair(pairRef,side,Number(b.dataset.factor));if(!next)return;stop();visit.pairs.set(caseId,next);visit.comparison=false;const selector=undo?`[data-common-undo="${side}"]`:`[data-common-split="${side}"][data-factor="${b.dataset.factor}"]`;ctx.render();const candidate=document.querySelector(selector),reverse=document.querySelector(`[data-common-${undo?'split':'undo'}="${side}"]`);ctx.focus(candidate&&!candidate.disabled?selector:reverse&&!reverse.disabled?`[data-common-${undo?'split':'undo'}="${side}"]`:'#common-board-title');};
 on('[data-common-split]',b=>change(b,false));on('[data-common-undo]',b=>change(b,true));
 on('[data-common-compare]',()=>{if(exampleOpen||!compareCommonPair(pairRef))return;stop();visit.comparison=true;redraw('#common-comparison');});
 on('[data-common-example-open]',()=>{stop();visit.exampleOpen=true;visit.exampleFrame=0;redraw();});
 const moveExample=delta=>{if(!exampleOpen||!commonExample(frame+delta))return;stop();visit.exampleFrame=frame+delta;redraw(visit.exampleFrame===2?'[data-common-example-previous]':visit.exampleFrame===0?'[data-common-example-next]':delta>0?'[data-common-example-next]':'[data-common-example-previous]');};
 on('[data-common-example-next]',()=>moveExample(1));on('[data-common-example-previous]',()=>moveExample(-1));
 on('[data-common-example-close]',()=>{if(!exampleOpen)return;stop();visit.exampleOpen=false;redraw('[data-common-example-open]');});
 root.querySelector('[data-common-cut-help]')?.addEventListener('toggle',()=>{if(live())stop();});
 // Guard before the existing local-speech target listener; do not rerender its first native click.
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(b&&root.contains(b)){if(!live()||!allowed(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=visibleNarration(root);}},{capture:true});
}
